fn main() {
    let number = 7;

    if number < 5 {
        println!("Меньше 5");
    } else if number < 10 {
        println!("От 5 до 9");
    } else {
        println!("10 или больше");
    }
}

fn main() {
    let condition = true;
    let number = if condition { 5 } else { 6 };
    println!("number = {}", number); // 5

    // Типы веток должны совпадать!
    // let error = if condition { 5 } else { "six" }; // Ошибка компиляции
}

fn main() {
    let x = 5;
    // if x { ... } // Ошибка: ожидается bool, найдено i32
    if x != 0 {     // Правильно: явное сравнение
        println!("Не ноль");
    }
}

fn main() {
    let mut count = 0;
    loop {
        count += 1;
        if count == 3 {
            break; // Выход из цикла
        }
    }
    println!("count = {}", count); // 3
}

fn main() {
    let mut counter = 0;
    let result = loop {
        counter += 1;
        if counter == 10 {
            break counter * 2; // Возврат значения
        }
    };
    println!("result = {}", result); // 20
}

fn main() {
    let mut number = 3;
    while number != 0 {
        println!("{}!", number);
        number -= 1;
    }
    println!("ПУСК!");
}

fn main() {
    // Итерация по диапазону
    for i in 1..=3 { // 1, 2, 3 (включительно)
        println!("{}", i);
    }

    // Итерация по массиву
    let arr = [10, 20, 30];
    for element in arr {
        println!("{}", element);
    }

    // Итерация по ссылке (чтобы не потребить массив)
    for element in &arr {
        println!("{}", element);
    }
}

fn main() {
    let mut count = 0;
    loop {
        count += 1;
        if count == 5 {
            break;
        }
    }
}

fn main() {
    for i in 1..=10 {
        if i % 2 == 0 {
            continue; // Пропускаем чётные
        }
        println!("Нечётное: {}", i);
    }
}

fn main() {
    'outer: loop {
        println!("Внешний цикл");
        loop {
            println!("Внутренний цикл");
            break 'outer; // Выход из внешнего цикла
        }
    }
    println!("Вышли из обоих циклов");
}

fn main() {
    'outer: for x in 0..5 {
        for y in 0..5 {
            if x == 2 && y == 2 {
                continue 'outer; // Переход к следующей итерации внешнего цикла
            }
            println!("x={}, y={}", x, y);
        }
    }
}

fn main() {
    let number = 3;
    match number {
        1 => println!("Один"),
        2 => println!("Два"),
        3 => println!("Три"),
        _ => println!("Другое"), // _ — catch-all (как default)
    }
}

fn main() {
    let x = 5;
    let result = match x {
        0 => "ноль",
        1..=5 => "от 1 до 5", // Диапазон
        6..=10 => "от 6 до 10",
        _ => "остальное",
    };
    println!("{}", result);
}

fn main() {
    let x = Some(5);
    match x {
        Some(n) if n < 10 => println!("Мало: {}", n), // Guard (страж)
        Some(n) => println!("Много: {}", n),
        None => println!("Ничего"),
    }
}

fn main() {
    for n in 1..=100 {
        let output = match (n % 3, n % 5) {
            (0, 0) => "FizzBuzz".to_string(),
            (0, _) => "Fizz".to_string(),
            (_, 0) => "Buzz".to_string(),
            _ => n.to_string(),
        };
        println!("{}", output);
    }
}

fn main() {
    let arr = [4, 8, 15, 16, 23, 42];
    let target = 16;
    let mut found = false;

    for (i, &val) in arr.iter().enumerate() {
        if val == target {
            println!("Найдено на индексе {}", i);
            found = true;
            break;
        }
    }
    if !found {
        println!("Не найдено");
    }
}

fn main() {
    'matrix: for i in 0..5 {
        for j in 0..5 {
            if i * j == 12 {
                println!("i={}, j={}", i, j);
                break 'matrix;
            }
        }
    }
}

fn main() {
    let temp = -5;
    let state = if temp < 0 { "ice" } else if temp < 100 { "water" } else { "steam" };
    println!("State: {}", state);
}
